class Solution {public:long long solve(int n,vector<vector<int>>edges,int required){struct E{int v,rev,cap;long long cost;};vector<vector<E>>a(n);for(auto e:edges){E f{e[1],(int)a[e[1]].size(),e[2],e[3]},b{e[0],(int)a[e[0]].size(),0,-1LL*e[3]};a[e[0]].push_back(f);a[e[1]].push_back(b);}int sent=0;long long total=0,inf=LLONG_MAX/4;while(sent<required){vector<long long>d(n,inf);vector<int>from(n,-1),index(n);d[0]=0;for(int pass=0;pass<n-1;pass++){bool change=false;for(int u=0;u<n;u++)if(d[u]!=inf)for(int id=0;id<(int)a[u].size();id++){auto&e=a[u][id];if(e.cap>0&&d[u]+e.cost<d[e.v]){d[e.v]=d[u]+e.cost;from[e.v]=u;index[e.v]=id;change=true;}}if(!change)break;}if(d[n-1]==inf)return -1;int amount=required-sent;for(int v=n-1;v;v=from[v])amount=min(amount,a[from[v]][index[v]].cap);for(int v=n-1;v;v=from[v]){auto&e=a[from[v]][index[v]];e.cap-=amount;a[v][e.rev].cap+=amount;}sent+=amount;total+=amount*d[n-1];}return total;}};